const configuredQueries = String($env.PROSPECTING_QUERIES || '').split(',').map((query) => query.trim()).filter(Boolean);
const queries = configuredQueries.length ? configuredQueries : [
  'site:linkedin.com/company "design" "Brasil"',
  'site:instagram.com "lançamento" "empresa" "Brasil"',
  'site:*.com.br "fale conosco" "marca"',
  'site:*.com.br "novo projeto" "empresa"'
];

return queries.slice(0, 10).map((query) => ({ json: { query } }));

const emailPattern = /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi;
const blockedDomains = ['google.com', 'facebook.com', 'instagram.com', 'linkedin.com', 'youtube.com'];
const sourceItems = $input.all();
const opportunities = [];

for (const item of sourceItems) {
  const results = Array.isArray(item.json.items) ? item.json.items : [];
  for (const result of results) {
    const text = [result.title, result.snippet, result.htmlSnippet, result.link].filter(Boolean).join(' ');
    const emails = [...new Set((text.match(emailPattern) || []).map((email) => email.toLowerCase()))];
    const link = String(result.link || '').trim();
    let hostname = '';
    try { hostname = new URL(link).hostname.replace(/^www\./, '').toLowerCase(); } catch {}
    if (!link || !hostname || blockedDomains.some((domain) => hostname === domain || hostname.endsWith('.' + domain))) continue;
    const normalizedKey = (emails[0] || hostname).toLowerCase();
    const relevanceTerms = ['empresa', 'marca', 'lançamento', 'lancamento', 'projeto', 'design', 'marketing', 'comunicação', 'comunicacao', 'produto'];
    const score = relevanceTerms.reduce((total, term) => total + text.toLocaleLowerCase('pt-BR').includes(term) * 10, 0);
    opportunities.push({
      json: {
        prospect_key: normalizedKey,
        prospect_name: String(result.title || hostname).replace(/\s+/g, ' ').trim().slice(0, 120),
        prospect_email: emails[0] || '',
        prospect_url: link,
        prospect_snippet: String(result.snippet || '').replace(/\s+/g, ' ').trim().slice(0, 500),
        relevance_score: Math.min(score, 100)
      }
    });
  }
}

const unique = new Map();
for (const opportunity of opportunities) {
  const current = unique.get(opportunity.json.prospect_key);
  if (!current || opportunity.json.relevance_score > current.json.relevance_score) unique.set(opportunity.json.prospect_key, opportunity);
}
return [...unique.values()].filter(({ json }) => json.relevance_score >= 20).slice(0, Number($env.PROSPECTING_DAILY_LIMIT || 10));

const candidates = $items('Qualificar oportunidades').map((item) => item.json);
const sentItems = $items('Buscar envios recentes').map((item) => item.json);
const sentText = sentItems.map((item) => JSON.stringify(item).toLowerCase()).join('\n');
const suppression = new Set(String($env.SUPPRESSION_EMAILS || '').split(',').map((email) => email.trim().toLowerCase()).filter(Boolean));
const autoSend = String($env.PROSPECTING_AUTOSEND || '').toLowerCase() === 'true';

return candidates.map((candidate) => {
  const email = String(candidate.prospect_email || '').trim().toLowerCase();
  const alreadyContacted = Boolean(email && sentText.includes(email)) || sentText.includes(String(candidate.prospect_url || '').toLowerCase());
  const suppressed = Boolean(email && suppression.has(email));
  const recipient = candidate.prospect_name || 'Olá';
  const subject = `Uma ideia para ${candidate.prospect_name}`;
  const body = [
    `Olá, ${recipient}!`,
    '',
    'Encontrei o trabalho de vocês em um canal público e achei que poderia contribuir com uma perspectiva de design e comunicação.',
    candidate.prospect_snippet ? `Contexto que chamou minha atenção: ${candidate.prospect_snippet}` : '',
    '',
    'Atuo com direção de arte, identidade visual, design digital e UI/UX. Se houver um projeto em andamento, posso compartilhar algumas ideias objetivas para o próximo passo.',
    '',
    `Referência pública: ${candidate.prospect_url}`,
    '',
    'Se não for relevante, basta responder “não entrar em contato” e não enviarei novas mensagens.',
    '',
    'Abraços,',
    'Rayssa Martins',
    'Diretora de Arte Sênior e Designer Multidisciplinar'
  ].filter(Boolean).join('\n');
  const action = suppressed || alreadyContacted ? 'skip' : (!email ? 'skip' : (autoSend ? 'send' : 'draft'));
  return { json: { ...candidate, prospect_email: email, prospect_subject: subject, prospect_body: body, already_contacted: alreadyContacted, suppressed, action } };
});
